WITH mine AS (
  DELETE FROM ai_reservations WHERE budget_key = $1::text AND item_key = $2::text AND owner = $3::text AND status = 'reserved'
  RETURNING amount
)
UPDATE ai_budget SET held = held - mine.amount, updated_at = now() FROM mine WHERE budget_key = $1::text
RETURNING held;

UPDATE ai_reservations SET status = 'unknown'
WHERE budget_key = $1::text AND item_key = $2::text AND owner = $3::text AND status = 'reserved'
RETURNING status;

INSERT INTO ai_budget_queue (budget_key, item_key, prompt) VALUES ($1::text, $2::text, $3::text)
ON CONFLICT (budget_key, item_key) DO NOTHING
RETURNING item_key;

